using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.LoyaltyDiscount;

public sealed class CalculatePayableTotalTests
{
    private readonly CalculatePayableTotal _useCase = new(new LoyaltyDiscountPolicy());

    [Fact]
    public void Gold_member_gets_five_percent_off_a_ten_thousand_cent_subtotal()
    {
        Assert.Equal(9_500, _useCase.For(10_000, LoyaltyTier.Gold));
    }

    [Fact]
    public void Gold_member_gets_five_percent_off_a_twenty_thousand_cent_subtotal()
    {
        Assert.Equal(19_000, _useCase.For(20_000, LoyaltyTier.Gold));
    }

    [Fact]
    public void Gold_member_gets_five_percent_off_a_five_thousand_cent_subtotal()
    {
        Assert.Equal(4_750, _useCase.For(5_000, LoyaltyTier.Gold));
    }

    [Fact]
    public void Gold_member_pays_nothing_when_the_subtotal_is_zero()
    {
        Assert.Equal(0, _useCase.For(0, LoyaltyTier.Gold));
    }
}
